const API = 'https://api.splitwise-lite.test';

// Loads a group: GET `${API}/groups/<id>` (id URL-encoded).
// The API answers with JSON like:
//   { "name": "Lisbon trip",
//     "members": [{ "name": "Ana" }, { "name": "Ben" }],
//     "expenses": [{ "description": "Dinner", "amount": 45.5,
//                    "paid_by": "Ana", "split_among": ["Ana", "Ben"] }] }
// and loadGroup resolves with Splitwise-lite's own shape:
//   { name: "Lisbon trip", members: ["Ana", "Ben"],
//     expenses: [{ description: "Dinner", amountCents: 4550,
//                  paidBy: "Ana", splitAmong: ["Ana", "Ben"] }] }
// If the response is not ok, it rejects with
//   "Could not load group <id> (HTTP <status>)".
async function loadGroup(groupId, fetchImpl = fetch) {
  const response = await fetchImpl(`${API}/groups/${encodeURIComponent(groupId)}`);
  if (!response.ok) {
    throw new Error(`Could not load group ${groupId} (HTTP ${response.status})`);
  }
  const data = await response.json();
  return {
    name: data.name,
    members: data.members.map((member) => member.name),
    expenses: data.expenses.map((e) => ({
      description: e.description,
      amountCents: Math.round(e.amount * 100),
      paidBy: e.paid_by,
      splitAmong: e.split_among,
    })),
  };
}

