// Builds a real Response, like the one fetch resolves with.
const jsonResponse = (body, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

const apiGroup = {
  name: 'Lisbon trip',
  members: [{ name: 'Ana' }, { name: 'Ben' }],
  expenses: [{ description: 'Dinner', amount: 45.5, paid_by: 'Ana', split_among: ['Ana', 'Ben'] }],
};

describe('loadGroup', () => {
  test('requests the group by id', async () => {
    const fetchMock = vi.fn().mockResolvedValue(jsonResponse(apiGroup));

    await loadGroup('lisbon', fetchMock);

    expect(fetchMock).toHaveBeenCalledWith('https://api.splitwise-lite.test/groups/lisbon');
  });

  test("converts the API's shape into Splitwise-lite's", async () => {
    const fetchMock = vi.fn().mockResolvedValue(jsonResponse(apiGroup));

    const group = await loadGroup('lisbon', fetchMock);

    expect(group).toEqual({
      name: 'Lisbon trip',
      members: ['Ana', 'Ben'],
      expenses: [{ description: 'Dinner', amountCents: 4550, paidBy: 'Ana', splitAmong: ['Ana', 'Ben'] }],
    });
  });

  test('rejects with the status when the response is not ok', async () => {
    const fetchMock = vi.fn().mockResolvedValue(jsonResponse({ error: 'Not found' }, 404));

    await expect(loadGroup('nope', fetchMock)).rejects.toThrow('Could not load group nope (HTTP 404)');
  });
});
